 void SpawnStep(float dt){if(BossSpawnStep())return;spawn-=dt;if(spawn>0)return;spawn=RunMode==SurvivorMode.Endless?.65f:.8f;int wave=CombatWave,count=0;foreach(var e in enemies)if(e.active&&e.type!=4)count++;if(count>=Mathf.Min(RoomMonsterLimit,SurvivorRules.MonsterLimit(wave)))return;var available=new List<Enemy>();foreach(var candidate in enemies)if(candidate.type!=4&&!candidate.active&&candidate.deathRemaining<=0&&wave>=SurvivorBestiary.Creatures[candidate.type].wave)available.Add(candidate);if(available.Count>0){var chosen=available[rng.Next(available.Count)];if(Spawn(chosen,chosen.type)){spawnSequence++;if(ChooseElite())PromoteElite(chosen);}}}

 bool Spawn(Enemy e,int type){var definition=SurvivorBestiary.Creatures[type];var radius=SurvivorBestiary.Radii;if(SurvivorBestiary.Flying(type))return SpawnFlyer(e,type,radius[type],definition.speed,definition.damage,definition.health,SurvivorBestiary.Experience[type]);if(!FindGroundSpawn(type,radius[type],out var p,out var ceiling))return false;int wave=CombatWave;e.type=type;e.radius=radius[type];e.speed=definition.speed*(type==4?1:Mathf.Pow(1.1f,wave-1))*enemySpeedBonus;e.damage=definition.damage*enemyDamageBonus;e.hp=Mathf.CeilToInt(definition.health*(type==4?1:Mathf.Pow(1.2f,wave-1)));e.maxHp=e.hp;e.generation++;e.deathRemaining=e.vulnerable=e.burnTick=0;e.exp=SurvivorBestiary.Experience[type];e.active=true;e.attack=e.repath=e.sword=e.poison=e.freeze=e.slow=e.burn=0;e.aoe=2.5f;e.telegraph=0;e.freeze=freezePulseRemaining;e.falling=type==3;e.y=p.y;e.go.transform.position=p+Vector3.up*(type==3?ceiling-p.y:0);e.go.SetActive(true);SetVisual(e);PrepareEnemy(e);e.animator.Respawn();return true;}
 void EnemyStep(float dt){var pp=EnemyGoal;foreach(var e in enemies){if(!e.active)continue;e.attack-=dt;e.sword-=dt;e.freeze=Mathf.Max(0,e.freeze-dt);e.vulnerable=Mathf.Max(0,e.vulnerable-dt);e.slow=Mathf.Max(0,e.slow-dt);if(e.burn>0){e.burn-=dt;e.burnTick-=dt;if(e.burnTick<=0){e.burnTick=.5f;Damage(e,Scaled(3),false);if(!e.active)continue;}}if(e.falling){var p=e.go.transform.position;p.y=Mathf.MoveTowards(p.y,e.y,2.5f*dt);e.go.transform.position=p;if(p.y<=e.y+.01f)e.falling=false;continue;}if(e.freeze>0)continue;if(ImpactMovement(e,dt))continue;
