 float dist=Distance(e.go.transform.position,pp);int cadence=dist>10?4:dist>6?2:1;if(tick%cadence!=Array.IndexOf(enemies,e)%cadence)continue;float delta=dt*cadence;e.repath-=delta;if(e.repath<=0||e.revision!=platform.Navigation.Revision){e.waypoint=platform.Navigation.Waypoint(e.go.transform.position,SurvivorEnemyCrowd.PursuitGoal(Array.IndexOf(enemies,e),enemies,pp,platform.Navigation),e.radius);e.repath=.4f;e.revision=platform.Navigation.Revision;}float speed=e.speed*(dist<2.5f?1.35f:1)*(e.slow>0?.7f:1)*(player.Owns(UpgradeId.GATHERING_AURA)?1.15f:1);if(player.Owns(UpgradeId.NETHER_POISON_DOMAIN)&&dist<player.range*2.7f)speed*=.5f;var next=SurvivorEnemyCrowd.Move(Array.IndexOf(enemies,e),enemies,e.waypoint,speed*delta,platform.Navigation);next.y=e.y;if(platform.Navigation.Contains(next,e.radius))e.go.transform.position=next;if((e.waypoint-next).sqrMagnitude<.01f)e.repath=0;Vector3 dir=RoomNavigation.Horizontal(pp-next);if(dir.sqrMagnitude>.01f)e.go.transform.rotation=Quaternion.LookRotation(dir);if(dist<e.radius+.18f+.2f&&e.attack<=0){e.animator.Attack();HitObjective(e.damage);e.attack=.75f;if(screen!=ScreenState.Playing)return;}}}
 void WeaponStep(float dt){for(int i=0;i<9;i++)cooldowns[i]-=dt;var p=PlayerPosition;var target=Nearest(p,player.range);
 if(cooldowns[1]<=0&&target!=null){var shotTargets=Targets(p,player.projectiles);int fired=0;for(int n=0;n<shotTargets.Count;n++){if(Distance(p,shotTargets[n].go.transform.position)>player.range)continue;foreach(var s in shots)if(!s.go.activeSelf){s.hit.Clear();s.life=player.range/6+.5f;s.pierce=player.pierce;s.damage=player.damage;s.go.transform.position=p+Vector3.up*.35f;Vector3 dir=(EnemyCenter(shotTargets[n])-s.go.transform.position).normalized;s.velocity=dir*6;s.go.SetActive(true);fired++;break;}}if(fired>0)Cue(FeedbackCue.Shot,p);cooldowns[1]=player.interval;}
 int swordCount=player.Owns(UpgradeId.ORBITING_SWORD)?Mathf.Min(14,(player.Stack(UpgradeId.ORBITING_SWORD)+2)*(player.Owns(UpgradeId.MYRIAD_SWORDS)?2:1)):0;orbit-=115*dt;for(int i=0;i<swords.Length;i++){swords[i].SetActive(i<swordCount);if(i>=swordCount)continue;float a=(orbit+360f*i/swordCount)*Mathf.Deg2Rad;var pos=p+new Vector3(Mathf.Cos(a)*1.05f,.5f,Mathf.Sin(a)*1.05f);swords[i].transform.SetPositionAndRotation(pos,SurvivorBladePose.OrbitRotation(orbit+360f*i/swordCount));foreach(var e in enemies)if(e.active&&!e.falling&&e.sword<=0&&Distance(pos,e.go.transform.position)<e.radius+.22f){e.sword=Mathf.Max(.05f,.35f*player.interval);Damage(e,Scaled((14+6*(player.Stack(UpgradeId.ORBITING_SWORD)-1))*(player.Owns(UpgradeId.MYRIAD_SWORDS)?2.2f:1)));}}
