 if(player.Owns(UpgradeId.LAVA_BOMB)&&cooldowns[5]<=0){var t=Nearest(p,20);if(t!=null){bool evo=player.Owns(UpgradeId.METEOR_LAVA);var center=t.go.transform.position;for(int meteor=0;meteor<(evo?3:1);meteor++){skillVisuals.Emit(evo?SkillVisual.MeteorLava:SkillVisual.LavaBomb,center+Vector3.up*.4f,.5f,Quaternion.identity);Area(center,1.25f*(evo?1.5f:1),Scaled(18*player.Stack(UpgradeId.LAVA_BOMB)),Color.red,true);}Cue(FeedbackCue.Explosion,center);}cooldowns[5]=2.2f*player.interval;}
 if(player.Owns(UpgradeId.GRAVITY_BLACK_HOLE)&&cooldowns[6]<=0){bool evo=player.Owns(UpgradeId.VOID_BLACK_HOLE);foreach(var e in Targets(p,evo?8:4)){var q=Vector3.MoveTowards(e.go.transform.position,p,evo?.4f:.2f);if(platform.Navigation.Contains(q,e.radius))e.go.transform.position=q;Damage(e,Scaled(8*player.Stack(UpgradeId.GRAVITY_BLACK_HOLE)));}skillVisuals.Emit(evo?SkillVisual.VoidHole:SkillVisual.BlackHole,p+Vector3.up*.2f,evo?3.1f:1.1f,Quaternion.identity);cooldowns[6]=3*player.interval;}
 if(player.Owns(UpgradeId.SWORD_RAIN)&&cooldowns[7]<=0){foreach(var e in Targets(p,5)){skillVisuals.Emit(SkillVisual.SwordRain,e.go.transform.position+Vector3.up*1.4f,.55f,SurvivorBladePose.RainRotation);Damage(e,Scaled(12*player.Stack(UpgradeId.SWORD_RAIN)));}cooldowns[7]=2.8f*player.interval;}
 if(player.Owns(UpgradeId.LIGHTNING_DOMAIN)&&cooldowns[8]<=0){Area(p,player.range*1.55f,Scaled(6*player.Stack(UpgradeId.LIGHTNING_DOMAIN)),Color.blue,false,true);skillVisuals.PulseDomain(true);cooldowns[8]=.4f*player.interval;}}
 void ShotStep(float dt){foreach(var s in shots){if(!s.go.activeSelf)continue;s.life-=dt;var from=s.go.transform.position;var to=from+s.velocity*dt;s.go.transform.position=to;if(s.life<=0){s.go.SetActive(false);continue;}foreach(var e in enemies){if(!e.active||(s.hit.TryGetValue(e,out var generation)&&generation==e.generation))continue;var a=from;var b=to;var c=EnemyCenter(e);var ab=b-a;float t=ab.sqrMagnitude>.0001f?Mathf.Clamp01(Vector3.Dot(c-a,ab)/ab.sqrMagnitude):0;if(Vector3.Distance(a+ab*t,c)>e.radius+.06f)continue;s.hit[e]=e.generation;Damage(e,s.damage);Chain(e,s.damage);if(s.pierce--<=0){s.go.SetActive(false);break;}}}}
 void Chain(Enemy first,int baseDamage){if(screen!=ScreenState.Playing||!player.Owns(UpgradeId.CHAIN_LIGHTNING))return;bool evo=player.Owns(UpgradeId.NINE_HEAVENS_THUNDER);var origin=first.go.transform.position;var prev=origin;int damage=Mathf.CeilToInt(baseDamage*(.45f+.15f*(player.Stack(UpgradeId.CHAIN_LIGHTNING)-1)));var targets=Targets(origin,enemies.Length);int bounce=0;foreach(var next in targets){if(next==first||Distance(origin,next.go.transform.position)>2.2f)continue;var nextPosition=next.go.transform.position;skillVisuals.Bolt(prev+Vector3.up*.3f,nextPosition+Vector3.up*.3f,evo);Damage(next,damage,false);if(evo&&next.active&&rng.NextDouble()<.3)next.freeze=1;prev=nextPosition;if(++bounce>=(evo?6:3))break;if(!evo)damage=Mathf.CeilToInt(damage*.8f);}}
 public void Damage(Enemy e,int amount,bool critical=true){if(screen!=ScreenState.Playing||!e.active||amount<=0)return;if(e.vulnerable>0)amount=Mathf.CeilToInt(amount*1.5f);bool isCritical=critical&&rng.NextDouble()<player.critChance;if(isCritical)amount=Mathf.CeilToInt(amount*player.critMultiplier);if(e.ward>0){int absorb=Mathf.Min(amount,Mathf.CeilToInt(e.ward));e.ward=Mathf.Max(0,e.ward-absorb);amount-=absorb;}e.hp=Mathf.Max(0,e.hp-amount);ImpactNumber(e,amount,isCritical);e.hitFlash=.12f;Cue(FeedbackCue.Hit,e.go.transform.position);e.animator.Hit();if(e.hp>0)return;e.active=false;e.animator.Die();e.deathRemaining=.45f;Cue(FeedbackCue.Kill,e.go.transform.position);if(e.type==4){BossDefeated();return;}player.kills++;RewardElite(e);TacticalKill(e);EliteBrood(e);Drop(new Vector3(e.go.transform.position.x,platform.Navigation.Floor,e.go.transform.position.z),e.exp*(player.Owns(UpgradeId.DOUBLE_CRYSTAL)&&rng.NextDouble()<.15?2:1));if(player.Owns(UpgradeId.KILL_HEAL))player.health=Mathf.Min(player.maxHealth,player.health+.5f);if(player.Owns(UpgradeId.EXPLOSIVE_REMAINS)){skillVisuals.Emit(SkillVisual.Explosion,e.go.transform.position+Vector3.up*.2f,.45f,Quaternion.identity);Area(e.go.transform.position,1,Scaled(8),Color.yellow);}ModeStep(0);}
 public void Hurt(float amount){if(screen!=ScreenState.Playing||rng.NextDouble()<player.dodge)return;float reduction=player.Owns(UpgradeId.NEAR_DEATH_PROTECTION)&&player.health<=player.maxHealth*.2f?.5f:0;amount=Mathf.Ceil(amount*(1-player.damageReduction)*(1-reduction));float absorb=Mathf.Min(player.shield,amount);player.shield-=absorb;player.health=Mathf.Max(0,player.health-(amount-absorb));shieldDelay=0;notice="受到伤害";feedback=.3f;DamageFlashUntil=Time.unscaledTime+.3f;Cue(FeedbackCue.Hurt,platform.Head.transform.position);if(player.health<=0)Finish(false);}
 void Finish(bool win){if(screen==ScreenState.Victory||screen==ScreenState.Defeat)return;SettleRun(win);runActive=false;ResetHandCombat();ResetEnemyAbilities();screen=win?ScreenState.Victory:ScreenState.Defeat;if(win)skillVisuals.Victory();Cue(win?FeedbackCue.Victory:FeedbackCue.Defeat,PlayerPosition);foreach(var s in shots)s.go.SetActive(false);}
 int Scaled(float damage)=>Mathf.CeilToInt(damage*player.damage/20f);
 public static float Distance(Vector3 a,Vector3 b)=>RoomNavigation.Horizontal(a-b).magnitude;
 Enemy Nearest(Vector3 p,float range){Enemy best=null;foreach(var e in enemies)if(e.active){float d=Distance(p,e.go.transform.position);if(d<=range){range=d;best=e;}}return best;}
 List<Enemy> Targets(Vector3 p,int count){var r=new List<Enemy>();foreach(var e in enemies)if(e.active)r.Add(e);r.Sort((a,b)=>Distance(p,a.go.transform.position).CompareTo(Distance(p,b.go.transform.position)));if(r.Count>count)r.RemoveRange(count,r.Count-count);return r;}
 void Area(Vector3 p,float radius,int damage,Color color,bool burn=false,bool paralyze=false){var targets=Targets(p,enemies.Length);foreach(var e in targets)if(e.active&&Distance(p,e.go.transform.position)<radius){Damage(e,damage);if(burn){e.burn=3;e.burnTick=.5f;}if(paralyze){skillVisuals.Bolt(p+Vector3.up*.05f,EnemyCenter(e),false);if(rng.NextDouble()<.1)e.freeze=.5f;}}if(!paralyze)Ring(p,radius,color,.4f);}
 void BuildPools(){for(int i=0;i<enemies.Length;i++){enemies[i]=new Enemy{go=new GameObject("Enemy "+i)};enemies[i].go.transform.SetParent(transform);enemies[i].go.SetActive(false);enemies[i].type=i<6?0:i<11?1:i<15?2:i<18?3:i==18?4:i<22?5:i<25?6:7+(i-25)/2;enemies[i].radius=SurvivorBestiary.Radii[enemies[i].type];SetVisual(enemies[i]);BuildEliteCrown(enemies[i]);enemies[i].healthBar=enemies[i].go.AddComponent<SurvivorEnemyHealthBar>();enemies[i].healthBar.Initialize(enemies[i],Resources.Load<Font>("Fonts/Chinese"));if(enemies[i].visual)enemies[i].visual.SetActive(false);}for(int i=0;i<shots.Length;i++){shots[i]=new Shot{go=SurvivorVisualCatalog.Create(SkillVisual.EnergyProjectile,transform)};shots[i].go.SetActive(false);}for(int i=0;i<crystals.Length;i++){crystals[i]=new Crystal{go=Instantiate(Resources.Load<GameObject>("Art/Weapons/ExperienceGem"),transform)};crystals[i].go.SetActive(false);}for(int i=0;i<swords.Length;i++){swords[i]=new GameObject("Orbiting Sword "+i);swords[i].transform.SetParent(transform,false);swords[i].SetActive(false);}for(int i=0;i<fx.Length;i++){fx[i]=new Fx{line=MakeLine("Skill FX",Color.cyan,.025f)};fx[i].line.enabled=false;}halo=MakeLine("Attack Range",Color.cyan,.014f);poisonRing=MakeLine("Poison Aura",Color.green,.025f);lightningRing=MakeLine("Lightning Domain",new Color(.4f,.4f,1),.02f);bossRing=MakeLine("Boss Telegraph",Color.red,.04f);}
 void SetVisual(Enemy e){if(e.visual)e.visual.SetActive(false);if(!e.visuals.TryGetValue(e.type,out var model)){model=Instantiate(Resources.Load<GameObject>("Art/Creatures/"+SurvivorBestiary.Creatures[e.type].model),e.go.transform);model.transform.localPosition=Vector3.zero;model.transform.localRotation=Quaternion.identity;model.transform.localScale=Vector3.one*SurvivorBestiary.Creatures[e.type].scale;e.visuals[e.type]=model;e.visualScales[e.type]=model.transform.localScale;}e.visual=model;e.baseScale=e.visualScales[e.type];model.transform.localScale=e.baseScale;model.SetActive(true);e.animator=model.GetComponent<SurvivorCreatureAnimator>();}
 GameObject Primitive(string name,PrimitiveType type,Vector3 scale,Color color){var go=GameObject.CreatePrimitive(type);go.name=name;go.transform.SetParent(transform);go.transform.localScale=scale;var collider=go.GetComponent<Collider>();if(collider)Destroy(collider);var m=new Material(Shader.Find("Standard")){color=color};m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*.5f);go.GetComponent<Renderer>().sharedMaterial=m;return go;}
 LineRenderer MakeLine(string name,Color color,float width){var go=new GameObject(name);go.transform.SetParent(transform);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=new Material(Shader.Find("Sprites/Default"));line.startColor=line.endColor=color;line.startWidth=line.endWidth=width;line.useWorldSpace=true;return line;}
 void RingShape(LineRenderer line,Vector3 p,float radius){line.positionCount=65;for(int i=0;i<65;i++){float a=i*Mathf.PI*2/64;line.SetPosition(i,p+new Vector3(Mathf.Cos(a)*radius,.035f,Mathf.Sin(a)*radius));}}
 void Ring(Vector3 p,float radius,Color c,float life){foreach(var f in fx)if(f.life<=0){f.life=f.max=life;f.center=p;f.radius=radius;f.ring=true;f.line.startColor=f.line.endColor=c;f.line.enabled=true;return;}}
 void Beam(Vector3 a,Vector3 b,Color c,float life){foreach(var f in fx)if(f.life<=0){f.life=f.max=life;f.ring=false;f.line.positionCount=2;f.line.SetPosition(0,a);f.line.SetPosition(1,b);f.line.startColor=f.line.endColor=c;f.line.enabled=true;return;}}
 bool WorldVisible=>screen==ScreenState.Playing||screen==ScreenState.Paused||screen==ScreenState.Upgrade||screen==ScreenState.Victory||screen==ScreenState.Defeat||screen==ScreenState.Camp;
 void Visuals(){UpdateHandVisual();foreach(var e in enemies)if(e.visual){bool show=WorldVisible&&(e.active||e.deathRemaining>0);if(e.visual.activeSelf!=show)e.visual.SetActive(show);}if(skillVisuals){skillVisuals.ReducedEffects=meta.lowEffects;skillVisuals.Refresh(player,PlayerPosition,WorldVisible);}if(screen==ScreenState.Victory||screen==ScreenState.Defeat)DeathStep(Time.unscaledDeltaTime);var pp=PlayerPosition;bool playing=WorldVisible;halo.enabled=playing;RingShape(halo,pp,player.range);poisonRing.enabled=lightningRing.enabled=bossRing.enabled=false;RefreshBossPresentation(playing);RefreshModePresentation(playing);RefreshEnemyAbilities(playing);RefreshCombatFeel(playing);RefreshTactics(playing);foreach(var enemy in enemies)enemy.healthBar.Refresh(enemy,platform.Head,playing,BossName); }
}
